    passos: ["Peça por escrito a cópia integral do prontuário.", "Procure segunda opinião médica.", "Denuncie, se quiser, ao Conselho Regional de Medicina.", "Procure a advogada para avaliar a ação."], urgente: ["Risco de perda de provas", "Prazo de 5 anos perto do fim"],
    fontes: [["Código de Defesa do Consumidor, arts. 14 e 27", "https://www.planalto.gov.br/ccivil_03/leis/l8078compilado.htm"]],
