    perguntas: [{ q: "O que você precisa?", a: ["Fertilização in vitro (FIV)", "Congelar óvulos antes de quimioterapia", "Tratamento de infertilidade (exames, cirurgia)"] }, { q: "O contrato prevê reprodução assistida?", a: ["Sim", "Não", "Não sei"] }, { q: "Há diagnóstico de doença associada?", a: ["Sim", "Não"] }],
