  "pad-prescricao": {
    acolhe: "A prescrição pode encerrar um processo disciplinar — e a contagem tem regras que nem sempre a administração observa.",
    perguntas: [{ q: "Qual a pena em jogo?", a: ["Advertência", "Suspensão", "Demissão ou cassação"], ajuda: ["pad"] }, { q: "Quando a autoridade soube do fato?", a: ["Menos de 2 anos", "De 2 a 5 anos", "Mais de 5 anos"] }, { q: "O fato também é crime?", a: ["Sim", "Não", "Não sei"] }],
    lei: ["Prescrição (federal): 5 anos para demissão, cassação e destituição; 2 anos para suspensão; 180 dias para advertência (Lei 8.112/1990, art. 142).", "O prazo começa quando o fato se torna conhecido; a abertura de sindicância ou PAD interrompe a contagem (art. 142, §§1º e 3º).", "Se o fato também é crime, vale o prazo de prescrição da lei penal (art. 142, §2º)."],
    juris: ["STJ, Súmula 635: o prazo começa quando a autoridade competente para abrir o processo toma conhecimento do fato; é interrompido pela primeira instauração válida e volta a correr por inteiro depois de 140 dias."],
    prazos: ["Faça a conta desde a ciência pela autoridade — pode ser o argumento central da defesa."], docs: ["Portaria de instauração", "Documentos que mostram quando a administração soube do fato", "Cópia integral do processo"],
    passos: ["Peça cópia integral do processo.", "Identifique a data da ciência do fato.", "Procure a advogada para alegar a prescrição."], urgente: ["Julgamento próximo", "Risco de demissão"],
    fontes: [["Lei 8.112/1990, art. 142", "https://www.planalto.gov.br/ccivil_03/leis/l8112cons.htm"], ["STJ — Súmulas", "https://scon.stj.jus.br/SCON/sumstj/"]],
  },
  "licitacao-recurso": {
    acolhe: "Em licitação os prazos são curtos — perder um dia pode significar perder o direito de recorrer.",
    perguntas: [{ q: "Contra o quê você quer recorrer?", a: ["O edital", "A habilitação ou inabilitação", "O julgamento das propostas", "A anulação ou revogação"] }, { q: "Qual a lei da licitação?", a: ["Lei 14.133/2021", "Lei de estatais (13.303/2016)", "Não sei"] }, { q: "Você manifestou intenção de recorrer na sessão?", a: ["Sim", "Não", "Não houve essa fase"] }],
    lei: ["Impugnação do edital ou pedido de esclarecimento: até 3 dias úteis antes da abertura (Lei 14.133/2021, art. 164).", "Recurso contra habilitação, inabilitação, julgamento das propostas, anulação ou revogação: 3 dias úteis da intimação ou da lavratura da ata (Lei 14.133/2021, art. 165, I).", "A intenção de recorrer deve ser manifestada imediatamente na sessão, quando o edital assim prever (art. 165, §1º)."],
    juris: ["Os tribunais de contas e o Judiciário costumam anular inabilitações por excesso de formalismo quando o vício é sanável."],
    prazos: ["3 dias úteis — conte com atenção."], docs: ["Edital e anexos", "Ata da sessão", "Proposta e documentos de habilitação", "Decisão recorrida"],
    passos: ["Manifeste a intenção de recorrer na sessão, se for o caso.", "Apresente o recurso em 3 dias úteis.", "Procure a advogada no mesmo dia da decisão."], urgente: ["Prazo de 3 dias correndo", "Contratação prestes a ser assinada"],
    fontes: [["Lei 14.133/2021", "https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm"]],
  },
  "orgao-nao-paga": {
    acolhe: "Empresa que presta serviço ao poder público e não recebe tem instrumentos para cobrar — e até para suspender ou encerrar o contrato.",
    perguntas: [{ q: "Há quanto tempo o pagamento atrasa?", a: ["Menos de 2 meses", "Mais de 2 meses"] }, { q: "A nota fiscal foi atestada (aprovada)?", a: ["Sim", "Não", "Não sei"] }, { q: "O contrato segue a lei:", a: ["14.133/2021", "8.666/1993 (contratos antigos)", "Não sei"] }],
    lei: ["A administração deve pagar na ordem cronológica das obrigações, sem pular credores sem justificativa (Lei 14.133/2021, art. 141).", "Atraso superior a 2 meses permite à empresa pedir a extinção do contrato ou suspender a execução (Lei 14.133/2021, art. 137, §§2º, IV, e 3º).", "Os valores atrasados devem ser corrigidos e acrescidos de juros, conforme o contrato e a lei."],
    juris: ["Condenações judiciais da Fazenda são pagas por precatório ou, se de pequeno valor, por RPV (Constituição, art. 100)."],
    prazos: ["Notifique o órgão formalmente e guarde o protocolo."], docs: ["Contrato e aditivos", "Notas fiscais atestadas", "Ordens de serviço e medições", "Notificações enviadas"],
    passos: ["Notifique o órgão cobrando o pagamento e a posição na ordem cronológica.", "Avalie suspender a execução após 2 meses de atraso.", "Procure a advogada para a cobrança judicial."], urgente: ["Risco de a empresa não pagar salários e tributos"],
    fontes: [["Lei 14.133/2021", "https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm"]],
  },
